<div class="key">并不是每种鸟都有全部六种行为。比如<b>杜鹃</b>把卵产在别的鸟（如苇莺）的巢里，由别的鸟代为孵卵、育雏，它自己<b>不筑巢、不孵卵、不育雏</b>；而<b>求偶、交配、产卵</b>是每种鸟都有的。</div>
