            { s: 2, p: '（2）答出“形成生殖细胞时成对的染色体分开（每对一条进入生殖细胞）”' },
            { s: 1, p: '（3）答出基因在染色体上' },
            { s: 2, p: '（3）答出“随染色体经精子传递，精子和卵细胞结合成受精卵，受精卵发育成个体”这条路线' }
