        {
          h: '化石：研究进化最直接、最重要的证据',
          html: `<p>几十亿年来生物是怎样一步步变化的？最有力的证据埋在地层里。<b>化石</b>是保存在地层中的古代生物的<b>遗体、遗物或生活痕迹</b>，比如恐龙的骨骼、植物叶片的印痕、动物的脚印、粪便等。它们是经过漫长的年代，由生物的遗体等被泥沙掩埋、矿物质渗入或留下印痕形成的。</p>
<div class="key">化石是研究生物进化<b>最直接、最重要</b>的证据。</div>
<p>地层是一层一层沉积形成的：<b>越靠下的地层形成得越早（越古老）</b>，越靠上的越晚。科学家比较不同地层中的化石，发现了规律：</p>
<table class="tbl"><tr><th>地层</th><th>其中的化石</th></tr>
<tr><td>越<b>古老</b>（靠下）的地层</td><td>化石生物越<b>简单、低等</b>，<b>水生</b>的越多</td></tr>
<tr><td>越<b>晚近</b>（靠上）的地层</td><td>化石生物越<b>复杂、高等</b>，<b>陆生</b>的越多</td></tr></table>
<p>根据化石在地层中出现的先后顺序，就能推断各类生物出现的先后，也就是进化的顺序。比如：最古老的含化石地层里主要是藻类和海洋无脊椎动物的化石，往上才依次出现鱼类、两栖类、爬行类、鸟类和哺乳类的化石。</p>
<p>有些化石还“身兼两类”的特征：比如有的鸟类化石既有鸟的特征（有羽毛、有翅膀），又保留着爬行动物的特征（口中有牙齿、翅膀末端有爪、有长长的尾椎骨）。这说明鸟类和爬行类有<b>较近的亲缘关系</b>，支持“鸟类是由古代爬行类进化来的”这一推测。</p>
<p class="warn">“地层越深，化石越高等”说反了；另外，化石记录是不完整的，很多生物没能留下化石，所以进化历程的某些环节还需要别的证据来补充。</p>`
        },
        {
          h: '比较法：从形态结构到分子',
          html: `<p>研究进化除了看化石，还常用<b>比较</b>的方法——比较不同生物的某些特征，找出它们的异同，推断亲缘关系的远近：</p>
<table class="tbl"><tr><th>比较什么</th><th>例子</th><th>说明什么</th></tr>
<tr><td>形态结构</td><td>人的手臂、鲸的鳍、蝙蝠的翼、鸟的翅膀，外形和功能很不一样，但骨骼的组成和排列基本相同</td><td>这些器官来自共同祖先的同一结构，说明它们有共同的祖先</td></tr>
<tr><td>胚胎发育</td><td>鱼、鸡、人的早期胚胎都有鳃裂和尾</td><td>脊椎动物有共同的祖先</td></tr>
<tr><td>分子水平</td><td>比较不同生物<b>细胞色素 c</b>（一种蛋白质）的氨基酸组成</td><td>差异越<b>小</b>，亲缘关系越<b>近</b>；差异越大，亲缘关系越远</td></tr></table>
<p>常见资料里，各种生物的细胞色素 c 与人的相比，氨基酸差异数大致如下（数据取自常见资料，只需比较相对大小）：</p>
<table class="tbl" style="text-align:center"><tr><th>生物</th><th>黑猩猩</th><th>猕猴</th><th>马</th><th>鸡</th><th>金枪鱼</th><th>果蝇</th><th>酵母菌</th></tr>
<tr><td>与人的差异（个）</td><td>0</td><td>1</td><td>12</td><td>13</td><td>21</td><td>27</td><td>44</td></tr></table>
<div class="key">看这类表只记一条：<b>差异越小，亲缘关系越近</b>。表中与人亲缘最近的是黑猩猩，最远的是酵母菌。</div>
<p class="warn">这类比较得出的是“亲缘关系的远近”和“有共同祖先”，不是“人是由黑猩猩进化来的”——人和黑猩猩是有共同祖先的两支，不是一支变成另一支。</p>`
        },
        {
          h: '进化树与进化的总趋势',
          html: `<p>把各类生物出现的先后和亲缘关系画成一棵“树”，就是<b>进化树</b>。树根是地球上最早的<b>原始单细胞生物</b>，由它们分别演化出植物和动物两大支：</p>
${treeFig(false)}
<table class="tbl"><tr><th></th><th>进化的主干顺序</th><th>说明</th></tr>
<tr><td><b>植物</b></td><td><b>藻类 → 苔藓植物 → 蕨类植物 → 裸子植物 → 被子植物</b></td><td>苔藓植物是从古代藻类分出的一个侧支；裸子植物和被子植物都由古代蕨类（种子植物的祖先）进化而来；被子植物出现最晚、最高等</td></tr>
<tr><td><b>动物</b></td><td><b>无脊椎动物 → 鱼类 → 两栖类 → 爬行类 → 鸟类 / 哺乳类</b></td><td>鱼类是最早的脊椎动物；<b>鸟类和哺乳类分别由古代爬行类进化而来</b>，是两个分支，不是鸟类再变成哺乳类</td></tr></table>
<div class="key">生物进化的总趋势：<br>① 由<b>简单</b>到<b>复杂</b>（单细胞 → 多细胞，结构越来越复杂）；<br>② 由<b>低等</b>到<b>高等</b>；<br>③ 由<b>水生</b>到<b>陆生</b>（藻类、鱼类生活在水中 → 苔藓、蕨类、两栖类离不开潮湿环境 → 种子植物、爬行类及以后真正适应陆地）。</div>
<p class="warn">① 进化树上“高等”不等于“后来的都比先前的强”——现在的藻类、细菌也活得很好，低等生物并没有被淘汰光；② 鸟类不是哺乳类的祖先，两者都来自古代爬行类；③ 顺序题里“苔藓→蕨类→藻类”这类把藻类放后面的都是错的。</p>`
        }
