          prompt: '<p>小明看了动物园里的黑猩猩后说：“人是猴子变的，黑猩猩再过几百万年就能变成人。”</p><p>请指出小明说法中的错误，并用“共同祖先 → 环境变化 → 直立行走 → 使用工具 → 脑发达、产生语言”的线索，简要说明人类是怎样起源的。</p>',
