          sample: '<p>错误有两处：① 人不是由现代的猴子或黑猩猩变来的，人类和现代类人猿（黑猩猩等）是由共同的祖先森林古猿进化来的两支，黑猩猩是人的“亲戚”，不是祖先；② 现代类人猿不会再进化成人，因为现在的环境与当年迫使森林古猿下地的环境完全不同，它们已经走上了另一条进化道路。</p><p>人类的起源：森林古猿原来在树上生活。后来气候变化、森林大量减少，一部分森林古猿被迫下到地面生活，逐渐学会直立行走（人猿分界的重要标志）；直立行走使前肢解放出来，可以使用树枝、石块，后来学会制造工具；制造和使用工具以及群体生活中的交流，又使脑容量增大、大脑越来越发达，并产生了语言，最终进化成人类。留在森林中的那部分森林古猿则进化成了现代类人猿。</p>',
