          html: `<p>武夷山国家公园主体位于福建北部，是我国首批设立的国家公园之一，也是世界文化与自然双遗产所在地。这里保存着完整的中亚热带原生性森林生态系统，动植物种类极为丰富，素有“蛇的王国”“鸟的天堂”“昆虫的世界”之称。国家公园划分为<b>核心保护区</b>和<b>一般控制区</b>：核心保护区原则上禁止人为活动；一般控制区限制开发建设，允许当地居民发展生态茶园、适度开展生态旅游和科普教育。</p>`
