          title: '材料：朱鹮的保护',
          html: `<p>朱鹮是一种美丽的涉禽，在稻田、河滩觅食泥鳅、小鱼、昆虫等，在高大的树上营巢。它曾一度被认为在我国野外已经灭绝，后来科学家在陕西洋县重新发现了极少数野生个体。为保护朱鹮，当地采取了一系列措施：在朱鹮栖息地建立自然保护区；要求朱鹮觅食的稻田不使用农药、化肥，并保留冬季有水的稻田；保护朱鹮营巢的高大树木；同时建立人工饲养繁育中心，对朱鹮进行人工繁育，再把繁育的个体野化后放归自然。经过多年努力，朱鹮的数量已大幅回升。</p>`
